-- 31-10-2026 (op verzoek HFC): AFAS Foundation bijgewerkt (enige financier, voorwaarden jaarverslag 2023, koers 2026) en regeling Challenge De Doorbraak 2026 toegevoegd.
-- Bronnen: afas.foundation/challenge-de-doorbraak; kleinegoededoelen.nl (8-9-2026); fondsenwerving.nl (19-5-2026); AFAS Foundation jaarverslag 2023; FAQ-video AFAS Foundation (opgave HFC).
update public.funders set
  aanvraagcriteria = 'AFAS Foundation wil de enige financier van een project zijn: cofinanciering door andere fondsen is geen uitgangspunt en past niet bij de werkwijze (opgave HFC op basis van de FAQ-video van AFAS Foundation). Aanvragen komen van stichtingen zonder winstoogmerk (Nederlandse ANBI of Belgische vzw) met een duidelijke maatschappelijke doelstelling en een solide organisatie. Alleen projectaanvragen worden behandeld; verzoeken om kennismakingsgesprekken niet. Indirecte kosten (organisatie- en wervingskosten) mogen maximaal 15% van de totale uitgaven zijn. Als het aangevraagde jaarbedrag lager is dan 50% van de liquide middelen van de aanvrager, gaat de Foundation ervan uit dat de organisatie het project zelf kan financieren. Vervolgaanvragen worden formeel beoordeeld op aantoonbare voortgang; het bestuur kiest voor "het project én de mensen" (vaste contactpersonen). Het bestuur wil minimaal 70% van het budget van het volgende jaar toekennen aan meerjarige projecten en partners; voor België is jaarlijks €250.000 beschikbaar. Niet in aanmerking: particulieren, crowdfunding, sponsorverzoeken, commerciële projecten en promotie- of wetenschappelijk onderzoek. Elk project krijgt een AFAS-medewerker als projectleider. (Bronnen: jaarverslag AFAS Foundation 2023; afas.foundation.)',
  algemene_beschrijving = coalesce(algemene_beschrijving,'') || ' Vanaf 2026 stuurt de Foundation nadrukkelijker op duurzame systeemverandering en langetermijnimpact: projecten die negatieve maatschappelijke patronen doorbreken, schaalbare oplossingen die lokaal eigenaarschap versterken en de zelfstandigheid van gemeenschappen vergroten. Daarbij wil zij ook kleinere organisaties financieren. Via de jaarlijkse challenge De Doorbraak zoekt zij plannen die problemen bij de bron aanpakken.',
  bijdrage_toelichting = 'Geen vast minimum of maximum; de bijdrage hangt af van ambitie, fase en onderbouwde behoefte. Jaarverslag 2023: 95 toekenningen, totaal €8,6 mln, van circa €1.600 tot €1.100.000; gemiddelde bijdrage rond €100.000. AFAS Foundation wil de enige financier van een project zijn.',
  research_source = coalesce(research_source,'') || ' | Bijgewerkt 31-10-2026 (Claude): FAQ-video (opgave HFC), afas.foundation/challenge-de-doorbraak, jaarverslag 2023, fondsenwerving.nl 19-5-2026',
  last_researched_at = now()
where id = 'c793e7e4-5574-433f-bfb5-4b0168b6c4d5';
insert into public.funder_themas (funder_id, thema_id) select 'c793e7e4-5574-433f-bfb5-4b0168b6c4d5', id from public.themas where naam in ('Sociale innovatie','Zorg') on conflict do nothing;
insert into public.funder_doelgroepen (funder_id, doelgroep_id) select 'c793e7e4-5574-433f-bfb5-4b0168b6c4d5', id from public.doelgroepen where naam in ('Kinderen','Patiënten') on conflict do nothing;

insert into public.subsidieregelingen (funder_id, naam, status, aanvraaglink, website, deadline, deadline_datum, deadline_omschrijving, cofinanciering, bijdrage_toelichting, algemene_beschrijving, voorwaarden, type_projecten, classification_reviewed, access_tier, data_tier, source_type, discovered_by, verified, status_laatst_gecheckt, plaats)
values ('c793e7e4-5574-433f-bfb5-4b0168b6c4d5', 'Challenge De Doorbraak 2026', 'gesloten',
 'https://www.afas.foundation/challenge-de-doorbraak', 'https://www.afas.foundation/challenge-de-doorbraak',
 'Indienen tot en met 18 oktober 2026; pitchdag 18 november 2026', '2026-10-18',
 'Plannen indienen kon tot en met 18 oktober 2026. Geselecteerde organisaties pitchen op woensdag 18 november 2026 in het AFAS Theater in Leusden; aan het eind van die dag wordt bekend welke initiatieven steun krijgen. Jaarlijks terugkerende challenge: houd de website in de gaten voor een volgende ronde.',
 'Geen cofinanciering: AFAS Foundation wil de enige financier zijn.',
 'Geen vast subsidieplafond of minimum; de bijdrage wordt afgestemd op de beoogde verandering, de fase van het project en wat nodig is om de verandering blijvend te maken. AFAS Foundation heeft jaarlijks minimaal €7 miljoen beschikbaar voor strategische, meerjarige programma''s (niet specifiek voor deze challenge).',
 'De Doorbraak is een challenge van AFAS Foundation voor stichtingen met een ambitieus, concreet plan voor blijvende systeemverandering: niet tijdelijk helpen, maar maatschappelijke problemen bij de bron aanpakken zodat een vastgelopen systeem daarna anders werkt. Denk aan organisaties die anders gaan samenwerken, verschuivende geldstromen, bewoners of lokale groepen die eigenaar worden, aangepast beleid of een aanpak die structureel wordt verankerd. Lokaal eigenaarschap is uitgangspunt. Het thema is vrij: onder meer onderwijs, zorg, armoede, voedsel, natuur en klimaat. Bestaande partners en nieuwe aanvragers kunnen meedoen; na een eerste selectie volgt een pitch.',
 'Het plan pakt een helder maatschappelijk probleem bij de oorzaak aan; duidelijk is welk systeem moet veranderen en waarom het nu niet werkt; het gaat verder dan één activiteit, voorziening of interventie; de belangrijkste partijen zijn vanaf het begin betrokken; eigenaarschap ligt niet alleen bij de aanvrager; er is een geloofwaardige route naar structurele verankering en een geplande exit van AFAS; de aanpak kan na de bijdrage doorgaan of groeien; de aanvrager kan uitleggen wat over vijf tot tien jaar aantoonbaar anders is. Niet: eenmalige activiteiten of evenementen, alleen bouw of aankoop van een voorziening, noodhulp, projecten afhankelijk van donaties, pilots zonder route naar structurele invoering, oplossingen die bij één initiatiefnemer liggen, of meer van hetzelfde.',
 'Systeemverandering; structurele aanpak van maatschappelijke problemen met lokaal eigenaarschap',
 true, 'pro', 'premium', 'internet_scan', 'handmatig', true, now(), 'Leusden');
insert into public.subsidieregeling_themas (subsidieregeling_id, thema_id) select s.id, t.id from public.subsidieregelingen s, public.themas t where s.naam='Challenge De Doorbraak 2026' and s.funder_id='c793e7e4-5574-433f-bfb5-4b0168b6c4d5' and t.naam in ('Sociale innovatie','Onderwijs','Zorg','Armoedebestrijding','Natuur en milieu','Klimaat') on conflict do nothing;
insert into public.subsidieregeling_doelgroepen (subsidieregeling_id, doelgroep_id) select s.id, t.id from public.subsidieregelingen s, public.doelgroepen t where s.naam='Challenge De Doorbraak 2026' and s.funder_id='c793e7e4-5574-433f-bfb5-4b0168b6c4d5' and t.naam in ('Gemeenschappen') on conflict do nothing;
insert into public.subsidieregeling_rondes (subsidieregeling_id, funder_id, type, naam, sluitingsdatum, status, toelichting, bron_url, actief)
select s.id, s.funder_id, x.type::public.datamoment_type, x.naam, x.d::date, 'gepland', x.toel, 'https://www.kleinegoededoelen.nl/afas-foundation-lanceert-nieuwe-challenge-de-doorbraak/', true
from public.subsidieregelingen s, (values ('aanvraagdeadline','De Doorbraak 2026 – indienen plannen','2026-10-18','Indienen tot en met 18 oktober 2026'),('overig','De Doorbraak 2026 – pitchdag AFAS Theater Leusden','2026-11-18','Geselecteerde organisaties pitchen; uitslag aan het eind van de dag')) x(type,naam,d,toel)
where s.naam='Challenge De Doorbraak 2026' and s.funder_id='c793e7e4-5574-433f-bfb5-4b0168b6c4d5';
